import java.util.*;
import java.io.*;

public class Main {
    static int[] solve(int[] boss, int[] startNode, long[] k) {
        // Write your solution here
        int[] ans = new int[startNode.length];
        Arrays.fill(ans, -1);
        return ans;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[] boss = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            boss[i] = (int) in.nval;
        }
        in.nextToken();
        int q = (int) in.nval;
        int[] startNode = new int[q];
        long[] k = new long[q];
        for (int i = 0; i < q; i++) {
            in.nextToken();
            startNode[i] = (int) in.nval;
            in.nextToken();
            k[i] = (long) in.nval;
        }
        int[] ans = solve(boss, startNode, k);
        StringBuilder sb = new StringBuilder();
        for (int x : ans) sb.append(x).append('\n');
        System.out.print(sb);
    }
}
